// İki giriş de buradan geçer:
//  • Webhook ile gelen istekte alanlar "body" içindedir,
//  • Workflow 05'in "/ai" komutuyla yaptığı çağrıda doğrudan gelir.
const j = $input.first().json || {};
const webhooktan = Object.prototype.hasOwnProperty.call(j, 'body');
const govde = webhooktan ? (j.body || {}) : j;
return [{ json: {
  soru: String(govde.soru || govde.mesaj || govde.text || '').trim(),
  chat_id: govde.chat_id ? String(govde.chat_id) : '',
  oturum: String(govde.oturum || govde.chat_id || 'varsayilan'),
  komut: String(govde.komut || '').trim().toLowerCase(),
  webhooktan,
} }];

// Okuma zinciri hata verdiyse: dosya gerçekten YOKSA boş listeyle devam edilir,
// ama dosya bozuk/erişilemez ise çalışma durdurulur — aksi hâlde liste boş
// sanılıp üzerine yazılır ve veriler kaybolur.
const _dosyaKontrol = (okuNode, cikarNode, dosya) => {
  const okuHata = $(okuNode).first().json.error;
  const okuMesaj = okuHata ? String(okuHata.message || okuHata) : '';
  if (/ENOENT|no such file|not found/i.test(okuMesaj)) return; // dosya henüz oluşmamış
  const cikarHata = $(cikarNode).first().json.error;
  if (okuHata || cikarHata) {
    const m = okuMesaj || String((cikarHata && cikarHata.message) || cikarHata);
    throw new Error(dosya + ' okunamadı; sohbet geçmişi korunsun diye durduruldu → ' + m);
  }
};
_dosyaKontrol('Sohbeti Oku', 'Sohbeti Çıkar', 'sohbet.json');


// Gelen soruyu, son konuşmalarla birlikte Ollama'ya gidecek biçime çevirir.
const istek = $('İsteği Al').first().json || {};
const soru = istek.soru;
const chatId = istek.chat_id;
const oturum = istek.oturum;
const komut = istek.komut;
const webhooktan = istek.webhooktan;

const okunan = $('Sohbeti Çıkar').first().json || {};
const hepsi = (okunan.data && okunan.data.oturumlar) || {};
const oturumlar = (hepsi && typeof hepsi === 'object' && !Array.isArray(hepsi)) ? { ...hepsi } : {};
const gecmis = Array.isArray(oturumlar[oturum]) ? oturumlar[oturum].slice() : [];

// /sifirla → bu oturumun geçmişini sil, modele hiç gitme
if (komut === 'sifirla' || /^\/?(sifirla|sıfırla|temizle)$/i.test(soru)) {
  oturumlar[oturum] = [];
  return [{ json: {
    atla: true, oturum, chatId, webhooktan, oturumlar, yazilsin: true,
    cevap: '🧹 Sohbet geçmişi temizlendi.',
  } }];
}

if (!soru) {
  return [{ json: {
    atla: true, oturum, chatId, webhooktan, oturumlar, yazilsin: false,
    cevap: 'Soru boş. Örnek: {"soru": "n8n nedir?"}',
  } }];
}

// Son 10 tur (20 mesaj) hatırlanır — küçük modeller uzun geçmişte dağılır.
const son = gecmis.slice(-20);
const mesajlar = [
  { role: 'system', content: 'Sen kullanıcının kendi bilgisayarında çalışan yardımcı bir asistansın. Türkçe, kısa ve net cevap ver. Bilmediğin şeyi uydurma.' },
  ...son.map((m) => ({ role: m.rol === 'ben' ? 'user' : 'assistant', content: String(m.metin || '') })),
  { role: 'user', content: soru },
];

return [{ json: {
  atla: false, oturum, chatId, webhooktan, soru, oturumlar,
  model: String($env.OLLAMA_MODEL || 'qwen2.5:3b').trim(),
  mesajlar,
} }];

// Ollama'ya yalnızca gerçekten soru varsa gidilir (/sifirla ve boş soru atlanır).
const j = $input.first().json;
return j.atla ? [] : [{ json: j }];

// Ollama'nın cevabını alır, geçmişe ekler ve gönderilecek metni kurar.
const hazirlik = $('Soruyu Hazırla').first().json || {};
const oturum = hazirlik.oturum;
const oturumlar = { ...(hazirlik.oturumlar || {}) };

const yanit = $input.first().json || {};
if (yanit.error || !(yanit.message && yanit.message.content)) {
  const ham = String((yanit.error && (yanit.error.message || yanit.error.description)) || yanit.error || '');
  const dusuk = ham.toLowerCase();
  let aciklama;
  if (/econnrefused|enotfound|getaddrinfo|socket hang up/.test(dusuk)) {
    aciklama = 'Ollama çalışmıyor gibi. Başlatmak için:\ndocker compose --profile ai up -d';
  } else if (/404|not found|model/.test(dusuk)) {
    aciklama = 'Model bulunamadı. İndirmek için:\ndocker exec -it ollama ollama pull ' + (hazirlik.model || 'qwen2.5:3b');
  } else if (/timeout|etimedout|aborted/.test(dusuk)) {
    aciklama = 'Model zamanında cevap veremedi. İlk soru model belleğe yüklenirken yavaştır; tekrar deneyin ya da daha küçük bir model kullanın.';
  } else {
    aciklama = 'Yerel AI\'ya ulaşılamadı' + (ham ? ': ' + ham.slice(0, 200) : '.');
  }
  // Hata durumunda geçmişi BOZMA: soru da cevap da yazılmaz.
  return [{ json: { cevap: '⚠️ ' + aciklama, chatId: hazirlik.chatId, webhooktan: hazirlik.webhooktan, oturum, oturumlar, yazilsin: false } }];
}

const cevap = String(yanit.message.content).trim();
const simdi = new Date().toISOString();
const gecmis = Array.isArray(oturumlar[oturum]) ? oturumlar[oturum].slice() : [];
gecmis.push({ rol: 'ben', metin: hazirlik.soru, tarih: simdi });
gecmis.push({ rol: 'ai', metin: cevap, tarih: new Date().toISOString() });
// Oturum başına son 100 mesaj saklanır — dosya sınırsız büyümesin.
oturumlar[oturum] = gecmis.slice(-100);

return [{ json: { cevap, chatId: hazirlik.chatId, webhooktan: hazirlik.webhooktan, oturum, oturumlar, yazilsin: true } }];

// Modele hiç gidilmeyen durumlar (/sifirla, boş soru) buradan geçer.
// Model kolu çalıştıysa bu kol boş döner, böylece aşağısı iki kez çalışmaz.
const j = $input.first().json;
if (!j.atla) return [];
return [{ json: {
  cevap: j.cevap, chatId: j.chatId, webhooktan: j.webhooktan, oturum: j.oturum,
  oturumlar: j.oturumlar, yazilsin: !!j.yazilsin,
} }];

// Yanıt düğümü yalnızca webhook ile gelen isteklerde çalışmalı;
// workflow 05'ten gelen çağrıda yanıtlanacak bir HTTP isteği yoktur.
const j = $input.first().json;
return j.webhooktan ? [{ json: j }] : [];

// Soru Telegram'dan geldiyse (chat_id doluysa) cevap oraya da gider.
const j = $input.first().json;
if (!j.chatId) return [];
return [{ json: { chat_id: j.chatId, text: String(j.cevap).slice(0, 3900) } }];

// Dosyaya yalnızca oturum geçmişi yazılır.
const j = $input.first().json;
if (!j.yazilsin) return [];
return [{ json: { oturumlar: j.oturumlar } }];
